import{_ as o,o as a,c,a0 as t}from"./chunks/framework.BLL-IG04.js";const u=JSON.parse('{"title":"Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/concepts.md","filePath":"explanation/concepts.md"}'),s={name:"explanation/concepts.md"};function i(n,e,r,d,l,m){return a(),c("div",null,[...e[0]||(e[0]=[t('<h1 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to &quot;Concepts&quot;">​</a></h1><p>mimus&#39;s vocabulary centers on one idea: a <strong>claim</strong> is a statement in your repo that is either still true or quietly false, and every finding must carry <strong>evidence</strong> or not exist.</p><h2 id="entities" tabindex="-1">Entities <a class="header-anchor" href="#entities" aria-label="Permalink to &quot;Entities&quot;">​</a></h2><ul><li><strong>Claim</strong> — a checkable assertion extracted from a source: a backticked span, a code block, or a prose pattern. Always carries <code>source</code> + <code>line</code> so evidence can point back.</li><li><strong>Claim kind</strong> — the taxonomy bucket (<code>path</code>, <code>command</code>, <code>symbol</code>, <code>count</code>, <code>link</code>, <code>behavior</code>) that decides which checker applies. See <a href="./claims.html">claims &amp; tiers</a> for the table.</li><li><strong>Violation</strong> — a proven false claim: <code>claim + evidence + fix(optional)</code>. No evidence, no violation.</li><li><strong>Rule</strong> — a convention declared as data in <code>rules/*.toml</code> (regex + message + severity), verified by the rules checker. A bad rule regex is silence plus a <code>doctor</code> complaint — rules can never crash the gate.</li><li><strong>Trust score</strong> — <code>mimus audit</code>&#39;s verdict on a kuda card: how much of the card&#39;s provenance still matches source.</li></ul><h2 id="tiers" tabindex="-1">Tiers <a class="header-anchor" href="#tiers" aria-label="Permalink to &quot;Tiers&quot;">​</a></h2><ul><li><strong>Mechanical</strong> — deterministic, offline checkers (<code>fs</code>, <code>cmd</code>, <code>symbol</code>, <code>rules</code>). The <code>mimus check</code> gate; evidence is reproducible by anyone.</li><li><strong>Graph</strong> — the set-level pass (ADR-0002): claims become <code>(subject, relation, object)</code> triples bucketed by subject; contradictions, stale references, undocumented modules. Mechanical speed — buckets, not agents.</li><li><strong>Semantic</strong> — the <code>acp</code> checker asks an external agent to adjudicate fuzzy residue. Advisory only (<code>warn</code>), can never gate CI — that is load-bearing, not a limitation.</li></ul><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><p><code>[sources]</code> in <code>mimus.toml</code>: <code>docs</code> (markdown globs), <code>comments</code> (<code>///</code> and code comments), <code>cards</code> (the <code>.kuda/</code> artifacts — kuda&#39;s memory audited as claims too).</p><h2 id="sinks" tabindex="-1">Sinks <a class="header-anchor" href="#sinks" aria-label="Permalink to &quot;Sinks&quot;">​</a></h2><p>Where findings go: human-readable report, <code>--json</code> for machines, exit 1 for CI gating, and the <code>coverage</code> command&#39;s advisory symbol list (never part of the gate).</p>',10)])])}const p=o(s,[["render",i]]);export{u as __pageData,p as default};
